#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""MiniMCProto v2.0 (Rev 2.0.4) 先 TH 后 MC 四阶段受控固件升级与 ATSG 打包部署工具。"""

from __future__ import annotations

import argparse
from dataclasses import dataclass, field
import hashlib
import json
import os
import pathlib
import select
import struct
import sys
import termios
import time
from typing import Any, Callable, Dict, List, Optional, Tuple
import zlib


SOF_0 = 0x55
SOF_1 = 0xAA
NODE_AP = 0x01
NODE_MC = 0x02
NODE_TH = 0x03

FLAG_REQ_V2 = 0x05
FLAG_RESP_V2 = 0x06
FLAG_PRIO_REQ_V2 = 0x15
ROUTE_DIRECT = 0x00
ROUTE_CASCADED = 0x04

CMD_ACK = 0x00
CMD_GET_VERSION = 0x01
CMD_VERSION_REPORT = 0x02
CMD_PING = 0x03
CMD_PONG = 0x04
CMD_NACK = 0x06
CMD_SYSTEM_CONTROL = 0x1D
CMD_OTA_START = 0x20
CMD_OTA_DATA = 0x21
CMD_OTA_FINISH = 0x22
CMD_OTA_STATUS = 0x23
CMD_OTA_ABORT = 0x24  # 真实 MC/TH Bootloader 不支持主动取消，用于负例校验 NACK(0x04)

TRAILER_MAGIC = 0x41545347
TRAILER_STRUCT_VER = 0x00010000
BOARD_ID_MC = 0x43500001
BOARD_ID_TH = 0x42300001
MAX_TH_APP_BYTES = 241664
MAX_MC_APP_BYTES = 917504
CAP_FLAG_BOOT_MODE = 0x80000000

# Bootloader 0x02 版本上报能力位图常量（Bits 16..23 = 0x08 表示最大支持 8 * 64B = 512B 分块）
TH_BOOT_CAPABILITY = 0xE0080423
MC_BOOT_CAPABILITY = 0xC0080435

# OTA 数据分块尺寸协议常量（单位：字节，对齐 Rev 2.0.4 D3-A CHUNK_MAX_SIZE = 512U）
DEFAULT_OTA_CHUNK_SIZE = 512
MAX_OTA_CHUNK_SIZE = 512
MIN_OTA_CHUNK_SIZE = 64
TH_BOOT_CAPABILITY_MAX_CHUNK = ((TH_BOOT_CAPABILITY & 0x00FF0000) >> 16) * 64  # 0x08 * 64 = 512
MC_BOOT_CAPABILITY_MAX_CHUNK = ((MC_BOOT_CAPABILITY & 0x00FF0000) >> 16) * 64  # 0x08 * 64 = 512

# POSIX termios 支持的标准串口波特率白名单（严禁不在列表内的波特率静默回退）
SUPPORTED_POSIX_BAUDS = (
    9600, 19200, 38400, 57600, 115200, 230400, 460800,
    500000, 576000, 921600, 1000000, 1152000, 1500000, 2000000,
)


@dataclass
class NodeVersionSnapshot:
    """单节点 0x02 CMD_VERSION_REPORT 16 字节版本与会话快照。"""

    proto_major: int
    proto_minor: int
    fw_major: int
    fw_minor: int
    boot_id: int
    git_commit_short: int
    capability_flags: int

    @property
    def is_boot_mode(self) -> bool:
        """返回 capability_flags bit31 是否处于 Bootloader 模式。"""
        # Bit31=1 表示当前驻留于 Bootloader，Bit31=0 表示运行于 Application
        return (self.capability_flags & CAP_FLAG_BOOT_MODE) != 0


@dataclass
class UpgradeStageTrace:
    """四阶段升级执行轨迹与前后 boot_id/版本号核对证据。"""

    target_node: int
    before_ver: Optional[NodeVersionSnapshot] = None
    boot_ver: Optional[NodeVersionSnapshot] = None
    after_ver: Optional[NodeVersionSnapshot] = None
    progress_history: List[Tuple[str, int]] = field(default_factory=list)
    chunks_sent: int = 0
    chunk_retries: int = 0
    bytes_sent: int = 0
    proxy_active_observed: bool = False
    chunk0_cached_observed: bool = False
    passed: bool = False
    error_detail: str = ""


def calc_crc16_ccitt(data: bytes) -> int:
    """计算 CRC-16/CCITT-FALSE (Poly=0x1021, Init=0xFFFF, XorOut=0x0000)。"""
    if data is None:
        return 0
    # 按字节大端移入 16 位寄存器并逐位异或生成多项式 0x1021
    crc = 0xFFFF
    for byte_val in data:
        crc ^= (byte_val & 0xFF) << 8
        for _ in range(8):
            if (crc & 0x8000) != 0:
                crc = ((crc << 1) ^ 0x1021) & 0xFFFF
            else:
                crc = (crc << 1) & 0xFFFF
    return crc & 0xFFFF


def calc_crc32_ieee(data: bytes) -> int:
    """计算标准 IEEE 802.3 CRC32 无符号 32 位校验和。"""
    if data is None:
        return 0
    # 调用 zlib.crc32 并转为无符号 32 位整型
    return zlib.crc32(data) & 0xFFFFFFFF


def build_cortex_m4_mock_binary(size_bytes: int, seed: int = 0x10) -> bytes:
    """构造含合法 Cortex-M4 向量表头 (SP=0x20008000, Reset=0x08004001) 的测试固件镜像。"""
    # 前 8 字节固定放置合法 SRAM 栈顶指针与带 Thumb 位 (bit0=1) 的 Reset_Handler 地址
    total = max(64, size_bytes)
    vec_hdr = struct.pack("<II", 0x20008000, 0x08004001)
    body = bytes(((seed + idx * 13) & 0xFF) for idx in range(total - 8))
    return vec_hdr + body


def pack_atsg_firmware_package(raw_bin: bytes, board_id: int, fw_version: int) -> bytes:
    """为裸固件附加 128 字节 ATSG Trailer 并输出完整升级包字节流。"""
    payload = raw_bin or b""
    digest = hashlib.sha256(payload).digest()
    # 先打包 Trailer 前 124 字节，再在末尾附加前 124 字节的 IEEE CRC32
    head_124 = struct.pack(
        "<IIIII32s32s32s8s",
        TRAILER_MAGIC,
        TRAILER_STRUCT_VER,
        board_id & 0xFFFFFFFF,
        fw_version & 0xFFFFFFFF,
        len(payload),
        digest,
        b"\x00" * 32,
        b"\x00" * 32,
        b"\x00" * 8,
    )
    trailer_crc = calc_crc32_ieee(head_124)
    return payload + head_124 + struct.pack("<I", trailer_crc)


def parse_and_verify_atsg_package(
    pkg_bytes: bytes,
    expected_board_id: int,
) -> Tuple[bool, str, Dict[str, Any]]:
    """解析并校验带 128B ATSG Trailer 的固件包（含魔数、板卡 ID、分区上限、SHA256 与 CRC32）。"""
    # 剥离末尾 128B Trailer 并依次验证魔数、结构版本、CRC32、board_id、尺寸上限与向量表
    if pkg_bytes is None or len(pkg_bytes) <= 128:
        return False, "ERR_PACKAGE_TOO_SMALL", {}
    payload = pkg_bytes[:-128]
    trailer = pkg_bytes[-128:]
    magic, s_ver, b_id, fw_ver, p_len, sha_bytes = struct.unpack("<IIIII32s", trailer[:52])
    trailer_crc = struct.unpack("<I", trailer[124:128])[0]
    if magic != TRAILER_MAGIC:
        return False, "ERR_BAD_TRAILER_MAGIC", {}
    if s_ver != TRAILER_STRUCT_VER:
        return False, "ERR_BAD_STRUCT_VER", {}
    if calc_crc32_ieee(trailer[:124]) != trailer_crc:
        return False, "ERR_BAD_TRAILER_CRC32", {}
    if b_id != expected_board_id:
        return False, "ERR_BOARD_ID_MISMATCH", {}
    max_limit = MAX_TH_APP_BYTES if expected_board_id == BOARD_ID_TH else MAX_MC_APP_BYTES
    if p_len != len(payload) or p_len == 0 or p_len > max_limit:
        return False, "ERR_IMAGE_OVERSIZE_OR_LEN", {}
    if hashlib.sha256(payload).digest() != sha_bytes:
        return False, "ERR_SHA256_MISMATCH", {}
    sp_val, pc_val = struct.unpack("<II", payload[:8])
    if not (0x20000000 <= sp_val <= 0x20060000) or (pc_val & 1) == 0 or not (0x08004000 <= pc_val <= 0x08100000):
        return False, "ERR_INVALID_VECTOR_TABLE", {}
    info = {
        "payload": payload, "trailer": trailer, "board_id": b_id, "fw_version": fw_ver,
        "payload_len": p_len, "fw_crc32": calc_crc32_ieee(payload), "trailer_crc32": trailer_crc,
    }
    return True, "OK", info


def encode_minimc_frame(
    dst_id: int,
    cmd_id: int,
    seq: int,
    payload: bytes = b"",
) -> bytes:
    """编码 AP 发往 MC(0x02) 或级联 TH(0x03) 的 MiniMCProto v2.0 请求帧。"""
    # 发往 TH(0x03) 时自动置位 ROUTE_CASCADED(0x04) 并将跳数设为 3；0x1D 置高优先级位
    is_routed = dst_id == NODE_TH
    hop = 3 if is_routed else 4
    route = ROUTE_CASCADED if is_routed else ROUTE_DIRECT
    flags = FLAG_PRIO_REQ_V2 if cmd_id == CMD_SYSTEM_CONTROL else FLAG_REQ_V2
    hdr = struct.pack(
        "<BBBBBBBBHH",
        SOF_0, SOF_1, NODE_AP, dst_id & 0xFF, flags, cmd_id & 0xFF,
        hop, route, seq & 0xFFFF, len(payload) & 0xFFFF,
    )
    crc = calc_crc16_ccitt(hdr + payload)
    return hdr + payload + struct.pack("<H", crc)


def decode_minimc_frame(raw: bytes) -> Tuple[bool, Dict[str, Any]]:
    """解码并验证单条 MiniMCProto v2.0 响应帧。"""
    # 校验帧长、SOF 魔数、v2 版本位及尾部 CRC-16/CCITT-FALSE
    if raw is None or len(raw) < 14:
        return False, {"error": "SHORT_FRAME"}
    sof0, sof1, src, dst, flags, cmd, hop, route, seq, plen = struct.unpack("<BBBBBBBBHH", raw[:12])
    if sof0 != SOF_0 or sof1 != SOF_1 or (flags & 0x0C) != 0x04 or len(raw) != 14 + plen:
        return False, {"error": "BAD_HEADER"}
    crc_calc = calc_crc16_ccitt(raw[: 12 + plen])
    crc_wire = struct.unpack("<H", raw[12 + plen : 14 + plen])[0]
    if crc_calc != crc_wire:
        return False, {"error": "CRC_FAIL"}
    return True, {
        "src_id": src, "dst_id": dst, "flags": flags, "cmd_id": cmd,
        "hop_limit": hop, "route_ctrl": route, "seq": seq,
        "payload_len": plen, "payload": raw[12 : 12 + plen],
    }


def decode_version_payload(payload: bytes) -> Optional[NodeVersionSnapshot]:
    """将 16 字节 0x02 CMD_VERSION_REPORT 载荷解析为 NodeVersionSnapshot。"""
    # 解包 16B 版本上报字段 (proto_major/minor, fw_major/minor, boot_id, git_sha, capability_flags)
    if payload is None or len(payload) < 16:
        return None
    p_maj, p_min, f_maj, f_min, boot_id, git_sha, cap = struct.unpack("<BBBBIII", payload[:16])
    return NodeVersionSnapshot(p_maj, p_min, f_maj, f_min, boot_id, git_sha, cap)


def encode_version_code(ver_spec: str) -> int:
    """将版本字符串（如 2.1、2.1.0.0 或 0x02010000）编码为 32 位 version_code。"""
    # 统一按 (major<<24)|(minor<<16)|(patch<<8)|build 布局编码，并兼容 0x 十六进制形式
    text = (ver_spec or "").strip()
    if not text:
        raise ValueError("empty version specification")
    if text.lower().startswith("0x"):
        val = int(text, 16)
        if val < 0 or val > 0xFFFFFFFF:
            raise ValueError(f"version_code out of uint32 range: {ver_spec}")
        return val
    if text.lower().startswith("v") and "." in text:
        text = text[1:]
    parts = [int(seg, 10) for seg in text.split(".")]
    if not (1 <= len(parts) <= 4) or any(p < 0 or p > 0xFF for p in parts):
        raise ValueError(f"invalid dotted version: {ver_spec}")
    while len(parts) < 4:
        parts.append(0)
    return (parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3]


class VirtualDualMcuOtaTarget:
    """支持 TH(AT32F423) 与 MC(AT32F435) 双节点四阶段升级与故障注入的确定性协议仿真靶机。"""

    def __init__(self) -> None:
        """初始化 MC 与 TH 节点的 App/Boot 状态、boot_id、版本号及 Flash 缓冲。"""
        # 为 MC(0x02) 与 TH(0x03) 初始化独立的运行态、OTA 状态机、Flash 区与安全互锁标志
        self.state: Dict[int, Dict[str, Any]] = {
            NODE_MC: {
                "in_boot": False, "fw_major": 1, "fw_minor": 2, "boot_id": 0x1000A001,
                "git_sha": 0x4FC171EA, "ota_state": 0, "expected_size": 0, "expected_crc": 0,
                "pending_ver": (1, 2), "next_offset": 0, "chunk0_ram": b"", "flash_buf": bytearray(),
                "erase_count": 0, "proxy_active": False, "steppers_disabled": False,
                "heaters_zeroed": False, "job_busy": False, "heater_target_deci_c": 0,
                "writer_locked": False, "anchor_valid": True,
            },
            NODE_TH: {
                "in_boot": False, "fw_major": 1, "fw_minor": 1, "boot_id": 0x2000B001,
                "git_sha": 0x769FCCBE, "ota_state": 0, "expected_size": 0, "expected_crc": 0,
                "pending_ver": (1, 1), "next_offset": 0, "chunk0_ram": b"", "flash_buf": bytearray(),
                "erase_count": 0, "anchor_valid": True, "steppers_disabled": False,
                "heaters_zeroed": False, "job_busy": False, "heater_target_deci_c": 0,
                "writer_locked": False,
            },
        }
        self.tx_log: List[str] = []

    def simulate_power_cycle_reset(self, node_id: int) -> None:
        """模拟节点断电冷重启：清空 RAM 暂存区并按首块向量表与 Anchor 完整性决定滞留 Boot 或进 App。"""
        st = self.state[node_id]
        # 断电后 RAM 中的 chunk0_ram 与进行中的 ota_state 归零，boot_id 自增刷新
        st["chunk0_ram"] = b""
        st["ota_state"] = 0
        st["next_offset"] = 0
        st["boot_id"] = (st["boot_id"] + 0x00200003) & 0xFFFFFFFF
        has_vector = len(st["flash_buf"]) >= 8 and bytes(st["flash_buf"][:4]) != b"\xFF\xFF\xFF\xFF"
        # 若首块向量表仍为 0xFFFFFFFF 或 Sector 127 Anchor 未提交，则强制滞留 Bootloader 等待重刷
        st["in_boot"] = not (has_vector and st.get("anchor_valid", True))

    def _pack_reply(self, src_id: int, cmd_id: int, seq: int, payload: bytes) -> bytes:
        """封装从 MC 或 TH 返回给 AP 的响应帧。"""
        # 构造带 FLAG_RESP_V2(0x06) 的响应头并计算 CRC16
        route = ROUTE_CASCADED if src_id == NODE_TH else ROUTE_DIRECT
        hop = 3 if src_id == NODE_TH else 4
        hdr = struct.pack(
            "<BBBBBBBBHH", SOF_0, SOF_1, src_id, NODE_AP, FLAG_RESP_V2, cmd_id, hop, route, seq, len(payload)
        )
        return hdr + payload + struct.pack("<H", calc_crc16_ccitt(hdr + payload))

    def _handle_ota_start(self, node_id: int, seq: int, payload: bytes) -> bytes:
        """处理 0x20 CMD_OTA_START 144B 载荷，执行擦除前零擦除门禁校验。"""
        st = self.state[node_id]
        # 若单写者锁被并发通道占用（如 USB U 盘升级中），立即返回 NACK(0x05 ERR_DEVICE_BUSY)
        if st.get("writer_locked", False):
            return self._pack_reply(node_id, CMD_NACK, seq, struct.pack("<BH", 0x05, seq))
        if not st["in_boot"] or len(payload) != 144:
            return self._pack_reply(node_id, CMD_NACK, seq, struct.pack("<BH", 0x06, seq))
        tgt_dev, _, _, _, fw_sz, fw_crc, new_ver = struct.unpack("<BBBBIII", payload[:16])
        trailer = payload[16:144]
        exp_board = BOARD_ID_TH if node_id == NODE_TH else BOARD_ID_MC
        max_sz = MAX_TH_APP_BYTES if node_id == NODE_TH else MAX_MC_APP_BYTES
        magic, s_ver, b_id, _, t_len = struct.unpack("<IIIII", trailer[:20])
        t_crc = struct.unpack("<I", trailer[124:128])[0]
        # 擦除前校验镜像大小上限（TH<=236KB, MC<=896KB），超限回 NACK 0x14 且零擦除
        if fw_sz == 0 or fw_sz > max_sz or t_len > max_sz:
            return self._pack_reply(node_id, CMD_NACK, seq, struct.pack("<BH", 0x14, seq))
        if (
            tgt_dev != node_id or magic != TRAILER_MAGIC or s_ver != TRAILER_STRUCT_VER
            or b_id != exp_board or t_len != fw_sz or calc_crc32_ieee(trailer[:124]) != t_crc
        ):
            return self._pack_reply(node_id, CMD_NACK, seq, struct.pack("<BH", 0x06, seq))
        st["erase_count"] += 1
        st["ota_state"] = 1
        st["expected_size"], st["expected_crc"] = fw_sz, fw_crc
        st["pending_ver"] = ((new_ver >> 24) & 0xFF, (new_ver >> 16) & 0xFF)
        st["next_offset"], st["chunk0_ram"] = 0, b""
        st["flash_buf"] = bytearray(b"\xFF" * fw_sz)
        st["anchor_valid"] = False
        return self._pack_reply(node_id, CMD_ACK, seq, struct.pack("<BBH", 1, 1, 0))

    def _handle_ota_data(self, node_id: int, seq: int, payload: bytes) -> bytes:
        """处理 0x21 CMD_OTA_DATA 分片写入（TH 首块 512B 暂存 RAM，后续块直写 Flash）。"""
        st = self.state[node_id]
        # 校验当前状态、分片长度（上限 MAX_OTA_CHUNK_SIZE=512B）、chunk_crc16 与单调递增偏移量
        if st["ota_state"] not in (1, 2, 3) or len(payload) < 9:
            return self._pack_reply(node_id, CMD_NACK, seq, struct.pack("<BH", 0x06, seq))
        offset, chunk_len, chunk_crc = struct.unpack("<IHH", payload[:8])
        data = payload[8:]
        if len(data) != chunk_len or chunk_len > MAX_OTA_CHUNK_SIZE:
            return self._pack_reply(node_id, CMD_NACK, seq, struct.pack("<BH", 0x02, seq))
        if calc_crc16_ccitt(data) != chunk_crc:
            return self._pack_reply(node_id, CMD_NACK, seq, struct.pack("<BH", 0x12, seq))
        if offset != st["next_offset"] or offset + chunk_len > st["expected_size"]:
            return self._pack_reply(node_id, CMD_NACK, seq, struct.pack("<BH", 0x13, seq))
        if node_id == NODE_TH and offset < MAX_OTA_CHUNK_SIZE:
            if offset == 0:
                sp_val, pc_val = struct.unpack("<II", data[:8])
                if not (0x20000000 <= sp_val <= 0x20060000) or (pc_val & 1) == 0:
                    return self._pack_reply(node_id, CMD_NACK, seq, struct.pack("<BH", 0x06, seq))
            st["chunk0_ram"] += bytes(data)
            st["ota_state"] = 2
        else:
            st["flash_buf"][offset : offset + chunk_len] = data
            st["ota_state"] = 3
        st["next_offset"] += chunk_len
        return self._pack_reply(node_id, CMD_ACK, seq, struct.pack("<BBH", 1, 1, 0))

    def _handle_ota_finish(self, node_id: int, seq: int, payload: bytes) -> bytes:
        """处理 0x22 CMD_OTA_FINISH 全镜像 CRC32 终验、TH 首块回写与复位切回新 App。"""
        st = self.state[node_id]
        # 校验累计写入字节数与全片 IEEE CRC32，通过后提交 Sector 127 Anchor 与首块向量表
        if len(payload) != 8 or st["next_offset"] != st["expected_size"]:
            return self._pack_reply(node_id, CMD_NACK, seq, struct.pack("<BH", 0x13, seq))
        fin_crc, action = struct.unpack("<IB", payload[:5])
        assembled = bytearray(st["flash_buf"])
        if node_id == NODE_TH and st["chunk0_ram"]:
            assembled[: len(st["chunk0_ram"])] = st["chunk0_ram"]
        calc_crc = calc_crc32_ieee(bytes(assembled))
        if calc_crc != st["expected_crc"] or calc_crc != fin_crc:
            st["ota_state"] = 5
            return self._pack_reply(node_id, CMD_NACK, seq, struct.pack("<BH", 0x12, seq))
        st["flash_buf"] = assembled
        st["ota_state"] = 4
        st["anchor_valid"] = True
        if action == 1:
            st["in_boot"] = False
            st["fw_major"], st["fw_minor"] = st["pending_ver"]
            st["boot_id"] = (st["boot_id"] + 0x01010005) & 0xFFFFFFFF
            if node_id == NODE_TH:
                self.state[NODE_MC]["proxy_active"] = False
        return self._pack_reply(node_id, CMD_ACK, seq, struct.pack("<BBH", 1, 1, 0))

    def _handle_sys_ctrl(self, dst: int, seq: int, pld: bytes) -> bytes:
        """处理 0x1D CMD_SYSTEM_CONTROL 请求：检查忙状态/加热互锁后关停外设并软复位进 Boot。"""
        st = self.state[dst]
        # 载荷长度必须严格等于 4B；打印忙或加热目标非零时拒绝进 Boot (NACK 0x05)
        if len(pld) != 4:
            return self._pack_reply(dst, CMD_NACK, seq, struct.pack("<BH", 0x02, seq))
        if st.get("job_busy", False) or st.get("heater_target_deci_c", 0) > 0:
            return self._pack_reply(dst, CMD_NACK, seq, struct.pack("<BH", 0x05, seq))
        action, _, _ = struct.unpack("<BBH", pld)
        st["steppers_disabled"] = True
        st["heaters_zeroed"] = True
        if action == 2:
            st["in_boot"] = True
            st["ota_state"] = 0
            st["boot_id"] = (st["boot_id"] + 0x00100001) & 0xFFFFFFFF
            if dst == NODE_TH:
                self.state[NODE_MC]["proxy_active"] = True
        return self._pack_reply(dst, CMD_ACK, seq, struct.pack("<BBH", 16, 8, 0))

    def exchange_frame(self, raw_req: bytes) -> bytes:
        """接收 AP 请求帧并返回对应节点 (MC 或级联 TH) 的二进制响应帧。"""
        # 解码请求帧并分发至支持的升级/查询处理器；未知命令(含 0x05/0x24)回 NACK 0x04
        ok, req = decode_minimc_frame(raw_req)
        if not ok:
            return self._pack_reply(NODE_MC, CMD_NACK, 0, struct.pack("<BH", 0x01, 0))
        dst, cmd, seq, pld = req["dst_id"], req["cmd_id"], req["seq"], req["payload"]
        st = self.state[dst]
        if cmd == CMD_GET_VERSION:
            cap = (TH_BOOT_CAPABILITY if dst == NODE_TH else MC_BOOT_CAPABILITY) if st["in_boot"] else 0x00080001
            v_pld = struct.pack("<BBBBIII", 2, 0, st["fw_major"], st["fw_minor"], st["boot_id"], st["git_sha"], cap)
            return self._pack_reply(dst, CMD_VERSION_REPORT, seq, v_pld)
        if cmd == CMD_SYSTEM_CONTROL:
            return self._handle_sys_ctrl(dst, seq, pld)
        if cmd == CMD_OTA_START:
            return self._handle_ota_start(dst, seq, pld)
        if cmd == CMD_OTA_DATA:
            return self._handle_ota_data(dst, seq, pld)
        if cmd == CMD_OTA_FINISH:
            return self._handle_ota_finish(dst, seq, pld)
        if cmd == CMD_OTA_STATUS:
            # 真实 MC/TH Bootloader 对带载荷的 0x23 一律回 NACK 0x06，不支持主动取消
            if len(pld) != 0:
                return self._pack_reply(dst, CMD_NACK, seq, struct.pack("<BH", 0x06, seq))
            c0_len = len(st["chunk0_ram"]) if dst == NODE_TH else 0
            return self._pack_reply(dst, CMD_OTA_STATUS, seq, struct.pack("<BBHI", st["ota_state"], 0, c0_len, st["next_offset"]))
        return self._pack_reply(dst, CMD_NACK, seq, struct.pack("<BH", 0x04, seq))


def _resolve_posix_baud_constant(baud: int) -> int:
    """解析并校验 POSIX termios 标准波特率常量（严禁未支持波特率静默回退）。"""
    # 仅允许白名单内且当前操作系统 termios 真实存在 B<baud> 常量的波特率，否则抛出 ValueError
    if baud <= 0 or baud not in SUPPORTED_POSIX_BAUDS:
        raise ValueError(f"unsupported baud={baud} (allowed: {SUPPORTED_POSIX_BAUDS})")
    b_const = getattr(termios, f"B{baud}", None)
    if not isinstance(b_const, int):
        raise ValueError(f"termios.B{baud} not available on this platform")
    return b_const


def _configure_serial_port(fd: int, baud: int) -> int:
    """使用 termios 将串口文件描述符配置为 8N1 原始模式与指定波特率并回读校验内核状态。"""
    # 解析精确波特率常量，配置 8N1 原始模式并通过 tcgetattr 回读校验 ispeed/ospeed 一致性
    b_const = _resolve_posix_baud_constant(baud)
    attrs = termios.tcgetattr(fd)
    attrs[0] = 0
    attrs[1] = 0
    attrs[2] = termios.CS8 | termios.CREAD | termios.CLOCAL | b_const
    attrs[3] = 0
    attrs[4] = b_const
    attrs[5] = b_const
    termios.tcsetattr(fd, termios.TCSANOW, attrs)
    verify_attrs = termios.tcgetattr(fd)
    if verify_attrs[4] != b_const or verify_attrs[5] != b_const:
        raise RuntimeError(f"termios baud readback mismatch for baud={baud}")
    return b_const


class SerialOtaTarget:
    """基于操作系统真实串口/PTY 文件描述符的 MiniMCProto v2.0 硬件通信靶机。"""

    def __init__(self, port: str, baud: int = 921600, timeout_s: float = 1.2) -> None:
        """打开目标串口设备并配置 termios 8N1 原始帧传输参数。"""
        # 保存串口路径、波特率与超时配置，以非阻塞读写模式打开设备并应用 termios 配置
        self.port = port
        self.baud = baud
        self.timeout_s = timeout_s
        self.fd = os.open(port, os.O_RDWR | os.O_NOCTTY | os.O_NONBLOCK)
        self.baud_const = _configure_serial_port(self.fd, baud)

    def close(self) -> None:
        """关闭已打开的串口文件描述符。"""
        # 确保底层文件描述符仅关闭一次并置为 -1
        if self.fd >= 0:
            os.close(self.fd)
            self.fd = -1

    def _read_until_len(self, buf: bytearray, target_len: int, deadline: float) -> bool:
        """在截止时间前从串口循环读取字节直至缓冲区达到 target_len。"""
        # 通过 select 监听可读事件并拼接字节流，避免忙轮询
        while len(buf) < target_len:
            rem = deadline - time.monotonic()
            if rem <= 0:
                return False
            rlist, _, _ = select.select([self.fd], [], [], rem)
            if not rlist:
                return False
            chunk = os.read(self.fd, target_len - len(buf))
            if not chunk:
                return False
            buf.extend(chunk)
        return True

    def exchange_frame(self, raw_req: bytes) -> bytes:
        """向串口写入 MiniMCProto v2.0 请求帧并按 12B 帧头定界读取完整响应帧。"""
        # 先将请求帧完整写入串口 fd，再按 0x55 0xAA 同步头与 payload_len 读取完整响应帧
        deadline = time.monotonic() + self.timeout_s
        mv = memoryview(raw_req)
        sent = 0
        while sent < len(raw_req):
            rem = deadline - time.monotonic()
            if rem <= 0:
                return b""
            _, wlist, _ = select.select([], [self.fd], [], rem)
            if not wlist:
                return b""
            sent += os.write(self.fd, mv[sent:])
        rx_buf = bytearray()
        while time.monotonic() < deadline:
            if not self._read_until_len(rx_buf, 2, deadline):
                return b""
            if rx_buf[0] == SOF_0 and rx_buf[1] == SOF_1:
                break
            del rx_buf[0]
        if not self._read_until_len(rx_buf, 12, deadline):
            return b""
        plen = struct.unpack("<H", rx_buf[10:12])[0]
        if plen > 1024 or not self._read_until_len(rx_buf, 14 + plen, deadline):
            return b""
        return bytes(rx_buf[: 14 + plen])


def _query_node_version(
    transceive: Callable[[bytes], bytes],
    node_id: int,
    seq: int,
) -> Optional[NodeVersionSnapshot]:
    """发送 0x01 CMD_GET_VERSION 并解码返回的 16 字节版本快照（支持复位窗口重试）。"""
    # 仅当收到合法的 0x02 CMD_VERSION_REPORT 响应帧时才解析返回快照
    for attempt in range(3):
        resp = transceive(encode_minimc_frame(node_id, CMD_GET_VERSION, seq + attempt, b""))
        ok, info = decode_minimc_frame(resp)
        if ok and info.get("cmd_id") == CMD_VERSION_REPORT:
            return decode_version_payload(info.get("payload", b""))
    return None


def _stage1_enter_boot(
    transceive: Callable[[bytes], bytes],
    node_id: int,
    trace: UpgradeStageTrace,
) -> bool:
    """执行第一阶段：0x01 预检快照、0x1D 受控进 Bootloader（支持断电滞留 Boot 挽救重入）。"""
    # 先采集升级前版本快照；若因前次断电已滞留 Bootloader，则直接复用当前 Boot 会话执行挽救升级
    trace.before_ver = _query_node_version(transceive, node_id, 1)
    trace.progress_history.append(("PRE_CHECK", 5))
    if trace.before_ver is None:
        trace.error_detail = "PRE_CHECK version query failed"
        return False
    if trace.before_ver.is_boot_mode:
        trace.boot_ver = trace.before_ver
        return True
    sys_pld = struct.pack("<BBH", 2, 1, 50)
    ok_ack, ack_info = decode_minimc_frame(transceive(encode_minimc_frame(node_id, CMD_SYSTEM_CONTROL, 2, sys_pld)))
    if not ok_ack or ack_info.get("cmd_id") != CMD_ACK:
        trace.error_detail = "0x1D CMD_SYSTEM_CONTROL not ACKed"
        return False
    trace.boot_ver = _query_node_version(transceive, node_id, 3)
    if trace.boot_ver is None or not trace.boot_ver.is_boot_mode or trace.boot_ver.boot_id == trace.before_ver.boot_id:
        trace.error_detail = "Bootloader entry verification failed"
        return False
    return True


def _send_chunk_with_retry(
    transceive: Callable[[bytes], bytes],
    node_id: int,
    seq: int,
    d_pld: bytes,
) -> Tuple[bool, int]:
    """发送单个 0x21 数据分片并在收到 CRC NACK 时自动重传（最多 3 次）。"""
    # 严格要求返回 0x00 CMD_ACK；遇到 NACK 时自动重试并统计重传次数
    retries = 0
    for attempt in range(3):
        ok_d, d_info = decode_minimc_frame(
            transceive(encode_minimc_frame(node_id, CMD_OTA_DATA, seq + attempt, d_pld))
        )
        if ok_d and d_info.get("cmd_id") == CMD_ACK:
            return True, retries
        retries += 1
    return False, retries


def _stage2_start_and_stream(
    transceive: Callable[[bytes], bytes],
    pkg_info: Dict[str, Any],
    trace: UpgradeStageTrace,
    chunk_size: int = DEFAULT_OTA_CHUNK_SIZE,
) -> bool:
    """执行第二阶段：0x20 144B 擦除准入与 0x21 分片流式写入（含分块边界校验、重传与 TH 首块 512B RAM 核验）。"""
    # 入口防御性校验 chunk_size 必须位于 1..MAX_OTA_CHUNK_SIZE (512B) 合法区间
    if chunk_size <= 0 or chunk_size > MAX_OTA_CHUNK_SIZE:
        trace.error_detail = f"invalid chunk_size={chunk_size} (must be 1..{MAX_OTA_CHUNK_SIZE})"
        return False
    node_id = trace.target_node
    start_pld = (
        struct.pack(
            "<BBBBIII", node_id, 1, 0, 0, pkg_info["payload_len"], pkg_info["fw_crc32"], pkg_info["fw_version"]
        )
        + pkg_info["trailer"]
    )
    ok_st, st_info = decode_minimc_frame(transceive(encode_minimc_frame(node_id, CMD_OTA_START, 4, start_pld)))
    if not ok_st or st_info.get("cmd_id") != CMD_ACK:
        trace.error_detail = "0x20 CMD_OTA_START rejected"
        return False
    trace.progress_history.append(("ERASING", 15))
    fw_raw: bytes = pkg_info["payload"]
    seq = 10
    for off in range(0, len(fw_raw), chunk_size):
        chunk = fw_raw[off : off + chunk_size]
        d_pld = struct.pack("<IHH", off, len(chunk), calc_crc16_ccitt(chunk)) + chunk
        ok_c, retries = _send_chunk_with_retry(transceive, node_id, seq, d_pld)
        trace.chunk_retries += retries
        seq += retries + 1
        if not ok_c:
            trace.error_detail = f"0x21 CMD_OTA_DATA failed at offset={off}"
            return False
        trace.chunks_sent += 1
        trace.bytes_sent += len(chunk)
        # 首块 512B 缓存完成时查询 0x23 验证 TH Bootloader SRAM 延迟提交态
        if node_id == NODE_TH and (off == 0 if chunk_size == MAX_OTA_CHUNK_SIZE else off + len(chunk) == MAX_OTA_CHUNK_SIZE):
            _, q_info = decode_minimc_frame(transceive(encode_minimc_frame(node_id, CMD_OTA_STATUS, seq, b"")))
            seq += 1
            if len(q_info.get("payload", b"")) == 8:
                o_st, _, c0_b, _ = struct.unpack("<BBHI", q_info["payload"])
                trace.chunk0_cached_observed = o_st == 2 and c0_b == MAX_OTA_CHUNK_SIZE
    trace.progress_history.append(("DOWNLOADING", 85))
    return True


def run_single_node_four_stage_upgrade(
    transceive: Callable[[bytes], bytes],
    node_id: int,
    pkg_bytes: bytes,
    chunk_size: int = DEFAULT_OTA_CHUNK_SIZE,
) -> UpgradeStageTrace:
    """对单个目标节点 (TH=0x03 或 MC=0x02) 执行完整四阶段受控升级与前后快照核对。"""
    # 依次推进 Stage 1~2；Stage 3 收到 0x22 ACK 仅封顶 95%，Stage 4 实测新 App 0x02 通过才置 100%
    trace = UpgradeStageTrace(target_node=node_id)
    if chunk_size <= 0 or chunk_size > MAX_OTA_CHUNK_SIZE:
        trace.error_detail = f"invalid chunk_size={chunk_size} (must be 1..{MAX_OTA_CHUNK_SIZE})"
        return trace
    exp_board = BOARD_ID_TH if node_id == NODE_TH else BOARD_ID_MC
    ok_pkg, msg_pkg, pkg_info = parse_and_verify_atsg_package(pkg_bytes, exp_board)
    if not ok_pkg:
        trace.error_detail = msg_pkg
        return trace
    if not _stage1_enter_boot(transceive, node_id, trace):
        return trace
    if not _stage2_start_and_stream(transceive, pkg_info, trace, chunk_size):
        return trace

    fin_seq = max(200, 12 + trace.chunks_sent + trace.chunk_retries)
    fin_pld = struct.pack("<IB3s", pkg_info["fw_crc32"], 1, b"\x00\x00\x00")
    ok_f, f_info = decode_minimc_frame(transceive(encode_minimc_frame(node_id, CMD_OTA_FINISH, fin_seq, fin_pld)))
    if not ok_f or f_info.get("cmd_id") != CMD_ACK:
        trace.error_detail = "0x22 CMD_OTA_FINISH failed"
        return trace
    trace.progress_history.append(("VERIFYING", 95))

    trace.after_ver = _query_node_version(transceive, node_id, fin_seq + 1)
    exp_maj = (pkg_info["fw_version"] >> 24) & 0xFF
    exp_min = (pkg_info["fw_version"] >> 16) & 0xFF
    if (
        trace.after_ver is None
        or trace.after_ver.is_boot_mode
        or (trace.after_ver.fw_major, trace.after_ver.fw_minor) != (exp_maj, exp_min)
        or trace.after_ver.boot_id in (trace.before_ver.boot_id, trace.boot_ver.boot_id)
    ):
        trace.error_detail = "Stage 4 post-reboot App verification failed"
        return trace
    trace.progress_history.append(("REBOOTING_VERIFIED", 100))
    trace.passed = True
    return trace


def run_ordered_th_then_mc_upgrade(
    rig: Any,
    th_pkg: bytes,
    mc_pkg: bytes,
    chunk_size: int = DEFAULT_OTA_CHUNK_SIZE,
) -> Tuple[bool, UpgradeStageTrace, UpgradeStageTrace]:
    """严格按“先 TH (0x03)、后 MC (0x02)”顺序执行双板四阶段升级闭环（默认 512B 分块）。"""
    # 强制先完成级联从节点 TH(0x03) 升级并验证新 App 上线，再启动主节点 MC(0x02) 升级
    th_trace = run_single_node_four_stage_upgrade(rig.exchange_frame, NODE_TH, th_pkg, chunk_size)
    if not th_trace.passed:
        return False, th_trace, UpgradeStageTrace(target_node=NODE_MC, error_detail="Skipped due to TH failure")
    mc_trace = run_single_node_four_stage_upgrade(rig.exchange_frame, NODE_MC, mc_pkg, chunk_size)
    return (th_trace.passed and mc_trace.passed), th_trace, mc_trace


def run_builtin_selftest() -> int:
    """运行 hil_deploy_via_minimc_ota.py 内置自检（512B 能力位解码 + 76,896B TH 151 块流式升级 + 先 TH 后 MC 闭环）。"""
    # 校验 TH(0xE0080423) 与 MC(0xC0080435) Bootloader 能力位 Bits 16..23 解码最大分块均为 512B
    if (
        DEFAULT_OTA_CHUNK_SIZE != 512
        or TH_BOOT_CAPABILITY_MAX_CHUNK != 512
        or MC_BOOT_CAPABILITY_MAX_CHUNK != 512
    ):
        sys.stderr.write("[FAIL] Bootloader capability max chunk constant mismatch\n")
        return 1
    # 构造真实 TH App 净荷尺寸 (76,896B -> 150*512B + 96B = 151 块) 与 MC 固件包执行默认 512B 四阶段升级
    rig = VirtualDualMcuOtaTarget()
    th_raw = build_cortex_m4_mock_binary(76896, seed=0x21)
    mc_raw = build_cortex_m4_mock_binary(2048, seed=0x42)
    th_pkg = pack_atsg_firmware_package(th_raw, BOARD_ID_TH, 0x02010000)
    mc_pkg = pack_atsg_firmware_package(mc_raw, BOARD_ID_MC, 0x02030000)
    ok, th_tr, mc_tr = run_ordered_th_then_mc_upgrade(rig, th_pkg, mc_pkg)
    if not ok or not th_tr.chunk0_cached_observed or th_tr.chunks_sent != 151 or th_tr.bytes_sent != 76896:
        sys.stderr.write(
            f"[FAIL] OTA self-test failed: th={th_tr.error_detail}, chunks={th_tr.chunks_sent}, mc={mc_tr.error_detail}\n"
        )
        return 1
    print(
        f"[PASS] hil_deploy_via_minimc_ota.py self-test passed: "
        f"chunk_size={DEFAULT_OTA_CHUNK_SIZE}B, TH(76896B/{th_tr.chunks_sent} chunks, "
        f"{th_tr.before_ver.fw_major}.{th_tr.before_ver.fw_minor}->{th_tr.after_ver.fw_major}.{th_tr.after_ver.fw_minor}) "
        f"then MC({mc_tr.before_ver.fw_major}.{mc_tr.before_ver.fw_minor}->{mc_tr.after_ver.fw_major}.{mc_tr.after_ver.fw_minor})."
    )
    return 0


def _build_cli_parser() -> argparse.ArgumentParser:
    """构建对齐部署说明书的命令行参数解析器（默认 --chunk-size 512）。"""
    # 注册自检、打包及说明书标准部署参数 (--port, --baud, --chunk-size, --th-pkg, --mc-pkg, --receipt-out)
    parser = argparse.ArgumentParser(description="MiniMCProto v2.0 (Rev 2.0.4) TH->MC OTA Deploy Tool")
    parser.add_argument("--self-test", action="store_true", help="Run built-in TH->MC 4-stage OTA self-test")
    parser.add_argument("--dry-run", action="store_true", help="Run dry-run package & protocol verification")
    parser.add_argument("--port", type=str, default="/dev/ttyUSB0", help="Serial port path (default: /dev/ttyUSB0)")
    parser.add_argument("--baud", type=int, default=921600, help="Serial baud rate (default: 921600)")
    parser.add_argument(
        "--chunk-size", type=int, default=DEFAULT_OTA_CHUNK_SIZE, help="OTA data chunk size in bytes (default: 512)"
    )
    parser.add_argument("--th-pkg", type=str, default="", help="Path to packed TH firmware package (fw_th.bin)")
    parser.add_argument("--mc-pkg", type=str, default="", help="Path to packed MC firmware package (fw_mc.bin)")
    parser.add_argument("--receipt-out", type=str, default="", help="Output path for JSON deployment receipt")
    parser.add_argument("--pack-in", type=str, default="", help="Input raw .bin to pack with 128B ATSG trailer")
    parser.add_argument("--pack-out", type=str, default="", help="Output path for packed .bin")
    parser.add_argument("--board", type=str, choices=["TH", "MC"], default="TH", help="Target board ID")
    parser.add_argument(
        "--version",
        type=str,
        default="2.1",
        help="Firmware version major.minor[.patch[.build]] or 0xAABBCCDD",
    )
    return parser


def _build_upgrade_receipt(
    args: argparse.Namespace,
    transport: str,
    th_tr: UpgradeStageTrace,
    mc_tr: UpgradeStageTrace,
) -> Dict[str, Any]:
    """构造包含串口参数、TH/MC 各自与总计分块/字节数及最终版本信息的 JSON 部署回执字典。"""
    # 提取 TH 与 MC 升级后的版本号并汇总分块数、字节数与整体通过标志
    th_ver = f"{th_tr.after_ver.fw_major}.{th_tr.after_ver.fw_minor}" if th_tr.after_ver else ""
    mc_ver = f"{mc_tr.after_ver.fw_major}.{mc_tr.after_ver.fw_minor}" if mc_tr.after_ver else ""
    passed = (th_tr.passed if args.th_pkg else True) and (mc_tr.passed if args.mc_pkg else True)
    return {
        "port": args.port, "baud": args.baud, "transport": transport, "chunk_size": args.chunk_size,
        "th_chunks_sent": th_tr.chunks_sent, "th_bytes_sent": th_tr.bytes_sent, "th_final_version": th_ver,
        "mc_chunks_sent": mc_tr.chunks_sent, "mc_bytes_sent": mc_tr.bytes_sent, "mc_final_version": mc_ver,
        "total_chunks": th_tr.chunks_sent + mc_tr.chunks_sent,
        "total_bytes": th_tr.bytes_sent + mc_tr.bytes_sent,
        "final_version": f"TH={th_ver},MC={mc_ver}" if (th_ver and mc_ver) else (th_ver or mc_ver),
        "passed": passed,
    }


def _run_cli_package_upgrade(args: argparse.Namespace) -> int:
    """执行命令行 --th-pkg / --mc-pkg 固件升级（默认走 SerialOtaTarget 真实串口通信并输出回执）。"""
    # 当 args.port != "virtual" 且非 dry-run 时，强制实例化 SerialOtaTarget 打开真实串口/PTY
    use_virtual = args.port == "virtual" or args.dry_run
    target: Any = VirtualDualMcuOtaTarget() if use_virtual else SerialOtaTarget(args.port, args.baud)
    transport = "virtual" if use_virtual else "serial"
    try:
        if args.th_pkg and args.mc_pkg:
            th_bytes = pathlib.Path(args.th_pkg).read_bytes()
            mc_bytes = pathlib.Path(args.mc_pkg).read_bytes()
            ok, th_tr, mc_tr = run_ordered_th_then_mc_upgrade(target, th_bytes, mc_bytes, args.chunk_size)
        elif args.th_pkg:
            th_bytes = pathlib.Path(args.th_pkg).read_bytes()
            th_tr = run_single_node_four_stage_upgrade(target.exchange_frame, NODE_TH, th_bytes, args.chunk_size)
            mc_tr = UpgradeStageTrace(target_node=NODE_MC)
            ok = th_tr.passed
        else:
            mc_bytes = pathlib.Path(args.mc_pkg).read_bytes()
            th_tr = UpgradeStageTrace(target_node=NODE_TH)
            mc_tr = run_single_node_four_stage_upgrade(target.exchange_frame, NODE_MC, mc_bytes, args.chunk_size)
            ok = mc_tr.passed
    finally:
        if hasattr(target, "close"):
            target.close()
    if args.receipt_out:
        receipt = _build_upgrade_receipt(args, transport, th_tr, mc_tr)
        pathlib.Path(args.receipt_out).write_text(json.dumps(receipt, indent=2), encoding="utf-8")
    return 0 if ok else 1


def main(argv: Optional[List[str]] = None) -> int:
    """hil_deploy_via_minimc_ota.py 命令行主入口。"""
    # 解析命令行参数并优先拦截非法 --chunk-size 或非法 --baud（返回非零退出码 2，严禁静默回退）
    parser = _build_cli_parser()
    args = parser.parse_args(argv)
    if args.chunk_size <= 0 or args.chunk_size > MAX_OTA_CHUNK_SIZE:
        sys.stderr.write(
            f"[EXPECTED-REJECT] invalid --chunk-size={args.chunk_size} (must be 1..{MAX_OTA_CHUNK_SIZE})\n"
        )
        return 2
    try:
        _resolve_posix_baud_constant(args.baud)
    except ValueError as exc:
        sys.stderr.write(f"[EXPECTED-REJECT] invalid --baud={args.baud}: {exc}\n")
        return 2
    if args.pack_in and args.pack_out:
        raw = pathlib.Path(args.pack_in).read_bytes()
        try:
            ver_code = encode_version_code(args.version)
        except ValueError as exc:
            sys.stderr.write(f"[EXPECTED-REJECT] invalid --version={args.version}: {exc}\n")
            return 2
        maj, min_v = (ver_code >> 24) & 0xFF, (ver_code >> 16) & 0xFF
        b_id = BOARD_ID_TH if args.board == "TH" else BOARD_ID_MC
        pkg = pack_atsg_firmware_package(raw, b_id, ver_code)
        pathlib.Path(args.pack_out).write_bytes(pkg)
        print(f"[PASS] Packed {len(raw)}B -> {len(pkg)}B ({args.board}, v{maj}.{min_v}, 0x{ver_code:08X})")
        return 0
    if args.th_pkg or args.mc_pkg:
        return _run_cli_package_upgrade(args)
    return run_builtin_selftest()


if __name__ == "__main__":
    sys.exit(main())

