} minimc_payload_sys_ctrl_t;

/**
 * @brief 128字节 ATSG 统一固件包尾部元数据结构体（Rev 2.0.4）
 */
typedef struct {
    uint32_t magic;               /**< 魔数 0x41545347 ("ATSG" 小端序) */
    uint32_t struct_version;      /**< 结构体版本 0x00010000 */
    uint32_t board_id;            /**< 板卡 ID（MC=0x43500001, TH=0x42300001） */
    uint32_t version_code;        /**< 固件版本号 ((major << 8) | minor) */
    uint32_t payload_len;         /**< 裸二进制固件载荷字节长度 */
    uint8_t  payload_sha256[32];  /**< 裸二进制载荷 SHA-256 摘要 */
    uint8_t  sig_r[32];           /**< 签名 R 分量（首版填 0） */
    uint8_t  sig_s[32];           /**< 签名 S 分量（首版填 0） */
    uint8_t  reserved[8];         /**< 保留对齐区（必须全 0） */
    uint32_t trailer_crc32;       /**< 前 124 字节 IEEE 802.3 CRC32 */
} minimc_fw_trailer_t;

