 * @return bool Stage 4 核实全部通过返回 true
 */
static bool verify_stage4_new_app_online(
    const fw_upgrade_exec_cfg_t* cfg,
    const fw_sealed_package_t* pkg,
    fw_updater_status_t* st
) {
    if (cfg == nullptr || pkg == nullptr || st == nullptr) return false;
    if (cfg->transport == nullptr) return false;
    const fw_ota_transport_t* tr = cfg->transport;
    const uint8_t max_polls = (cfg->stage4_max_polls > 0U) ? cfg->stage4_max_polls : 5U;
    for (uint8_t i = 0U; i < max_polls; ++i) {
        minimc_payload_version_report_t ver = {0, 0, 0, 0, 0, 0, 0};
        int16_t temp_deci = 0;
        if (!tr->query_version(tr->user_ctx, pkg->target_node, &ver)) continue;
        const bool is_app_mode = ((ver.capability_flags & MINIMC_CAP_FLAG_BOOT_MODE) == 0U);
        const bool new_boot_id = st->pre_upgrade_boot_id != 0U &&
            ver.boot_id != 0U && ver.boot_id != st->pre_upgrade_boot_id;
        // 配对 version_tool 使用 major<<24 | minor<<16 | build；16B 回包只回报主/次版本。
        const uint8_t expected_major = static_cast<uint8_t>(pkg->trailer.version_code >> 24U);
        const uint8_t expected_minor = static_cast<uint8_t>(pkg->trailer.version_code >> 16U);
        const bool ver_match = ver.major == expected_major && ver.minor == expected_minor;
        if (!is_app_mode || !new_boot_id || !ver_match) continue;
        const bool temperature_read = tr->query_temp_deci_c != nullptr &&
            tr->query_temp_deci_c(tr->user_ctx, pkg->target_node, &temp_deci);
        st->temperature_verified = temperature_read && temp_deci >= 50 && temp_deci <= 3000;
        if (!st->temperature_verified)
            std::snprintf(st->health_warning, sizeof(st->health_warning), "TEMPERATURE_NOT_VERIFIED");
        // 用户已确认本轮以新 App 身份为升级完成依据，温度失败保留为独立健康提示。
        st->post_upgrade_boot_id = ver.boot_id;
        st->progress_pct = 100U;
